import { useEffect, useState } from "react"
import type { RouteConfig } from "@mercurjs/dashboard-sdk"
import { Actions, Button, Card, Empty, Field, Message, Page, PageHeader, Status } from "../../spike/ui"
import {Select} from "../../components/ui/select"
import {Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from "../../components/ui/table"
declare const __BACKEND_URL__: string
export const config: RouteConfig = { label: "طلباتي", rank: 12 }
const api=async(path:string,init?:RequestInit)=>{const response=await fetch(`${__BACKEND_URL__}${path}`,{credentials:"include",...init,headers:{...(init?.body?{"content-type":"application/json"}:{}),...(init?.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||`HTTP ${response.status}`);return data}
const states=[["accepted","مقبول"],["processing","جاري التجهيز"],["ready_for_delivery","جاهز للتوصيل"],["with_courier","مع المندوب"],["delivered","تم التسليم"]] as const
const statusTone=(value:string):any=>value==="delivered"?"success":value==="accepted"?"warning":"info"
const statusLabel=(value:string)=>states.find(s=>s[0]===value)?.[1]||value||"—"
export default function VendorOrders(){const[orders,setOrders]=useState<any[]>([]),[selected,setSelected]=useState<any>(null),[message,setMessage]=useState(""),[busy,setBusy]=useState(false);const load=async()=>{const data=await api("/vendor/spike/orders");setOrders(data.orders||[])};useEffect(()=>{load().catch(e=>setMessage(e.message))},[]);const updateStatus=async(value:string)=>{if(!selected)return;try{setBusy(true);await api(`/vendor/spike/orders/${selected.id}/status`,{method:"POST",body:JSON.stringify({status:value})});setSelected({...selected,seller_status:value});setMessage("تم تحديث الحالة وإرسال إشعار للعميل");await load()}catch(e:any){setMessage(e.message||"تعذر تحديث الحالة")}finally{setBusy(false)}};return <Page><PageHeader title="طلباتي" description="تظهر هنا منتجات متجرك فقط بعد اعتماد الإدارة. التواصل مع العميل يتم عبر إدارة المنصة."/>{message&&<Message>{message}</Message>}<Card>{orders.length?<Table><TableHeader><TableRow><TableHead>الطلب</TableHead><TableHead>العميل</TableHead><TableHead>حصتك</TableHead><TableHead>الحالة</TableHead><TableHead>إجراء</TableHead></TableRow></TableHeader><TableBody>{orders.map(order=><TableRow key={order.id}><TableCell>#{order.display_id||order.id}</TableCell><TableCell><div>{order.shipping_address?.first_name||order.email||"—"}</div><small className="text-muted-foreground">{order.shipping_address?.phone||""}</small></TableCell><TableCell>{order.seller_subtotal} {order.currency_code}</TableCell><TableCell><Status tone={statusTone(order.seller_status)}>{statusLabel(order.seller_status)}</Status></TableCell><TableCell><Button tone="secondary" onClick={()=>setSelected(order)}>فتح</Button></TableCell></TableRow>)}</TableBody></Table>:<Empty>لا توجد طلبات حالياً.</Empty>}</Card>{selected&&<div className="spike-modal-backdrop" onMouseDown={()=>setSelected(null)}><div className="spike-edit-modal" onMouseDown={e=>e.stopPropagation()}><PageHeader title={`طلب #${selected.display_id||selected.id}`} description="تفاصيل العميل والمنتجات الخاصة بمتجرك." actions={<Button tone="ghost" onClick={()=>setSelected(null)}>×</Button>}/><div className="grid gap-3 md:grid-cols-2"><Card><h3>معلومات العميل</h3><p><b>الاسم:</b> {[selected.shipping_address?.first_name,selected.shipping_address?.last_name].filter(Boolean).join(" ")||"—"}</p><p><b>الهاتف:</b> {selected.shipping_address?.phone||"—"}</p><p><b>العنوان:</b> {[selected.shipping_address?.province,selected.shipping_address?.city,selected.shipping_address?.address_1].filter(Boolean).join(" - ")||"—"}</p></Card><Card><h3>حالة الطلب</h3><Field label="الحالة الحالية"><Select value={selected.seller_status||"accepted"} disabled={busy} onValueChange={updateStatus} options={states.map(s=>({value:s[0],label:s[1]}))}/></Field></Card></div><Card><h3>منتجاتك</h3><div className="space-y-2">{(selected.items||[]).map((item:any)=><div className="flex items-center justify-between rounded-xl bg-muted px-3 py-2" key={item.id}><span>{item.title||"منتج"}</span><b>× {item.quantity||1}</b></div>)}</div></Card><Actions><Button tone="secondary" onClick={()=>setSelected(null)}>إغلاق</Button></Actions></div></div>}</Page>}
